function validate([nums, limit]) {
  if (!Number.isInteger(limit) || limit < 1 || limit > 100000) return 'limit is a whole number from 1 to 10^5.';
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > limit)) return 'Each value is a whole number from 1 to limit.';
  return null;
}

