function minMoves(nums, limit) {
  const n = nums.length;
  const diff = new Array(2 * limit + 2).fill(0);
  for (let i = 0; i < n / 2; i++) {
    const low = Math.min(nums[i], nums[n - 1 - i]);
    const high = Math.max(nums[i], nums[n - 1 - i]);
    diff[2] += 2;
    diff[low + 1] -= 1;
    diff[low + high] -= 1;
    diff[low + high + 1] += 1;
    diff[high + limit + 1] += 1;
  }
  let best = n;
  let moves = 0;
  for (let target = 2; target <= 2 * limit; target++) {
    moves += diff[target];
    best = Math.min(best, moves);
  }
  return best;
}

