function minMoves(nums, limit) {
  // Try every possible common total and count, pair by pair, how many of its two values must change.
  const n = nums.length;
  let best = Infinity;
  for (let total = 2; total <= 2 * limit; total++) {
    let moves = 0;
    for (let i = 0; i < n / 2; i++) {
      const a = nums[i];
      const b = nums[n - 1 - i];
      if (a + b === total) continue;
      const fixA = total - b >= 1 && total - b <= limit;
      const fixB = total - a >= 1 && total - a <= limit;
      moves += fixA || fixB ? 1 : 2;
    }
    best = Math.min(best, moves);
  }
  return best;
}

