function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const limit = size === 'large' ? (rand() < 0.5 ? 100000 : 1 + pick(1000)) : 1 + pick(8);
  const n = size === 'large' ? 2000 : 2 * (1 + pick(6));
  const nums = new Array(n);
  // Some arrays start close to complementary around one total, so small answers show up too.
  const total = 2 + pick(2 * limit - 1);
  const near = rand() < 0.4;
  for (let i = 0; i < n / 2; i++) {
    let a = 1 + pick(limit);
    let b = 1 + pick(limit);
    if (near && rand() < 0.7 && total - a >= 1 && total - a <= limit) b = total - a;
    nums[i] = a;
    nums[n - 1 - i] = b;
  }
  return [nums, limit];
}
